mapper.select:
SELECT n.id, n.username, n.title, n.content, n.book_name, n.is_public, n.audit_status, n.audit_remark, n.create_time
FROM notes n
INNER JOIN (
    SELECT id FROM notes WHERE is_public = 1 AND audit_status = 2 ORDER BY RAND() LIMIT #{limit}
) t ON t.id = n.id
ORDER BY n.create_time DESC

mapper.update:
UPDATE notes
title = #{title}, content = #{content}, book_name = #{bookName}, is_public = #{isPublic}, audit_status = #{auditStatus},
WHERE id = #{id}

